import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { defineConfig, type Plugin } from 'vitest/config';

/** Recursively list files under a directory (posix-style relative paths). */
function listFiles(dir: string, base = dir): string[] {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) return listFiles(full, base);
    return [relative(base, full).split('\\').join('/')];
  });
}

/**
 * Generated by the art pipeline but never fetched by the game (QA metadata, the
 * old quest-card portraits, an unused UI plate): deployed, not precached.
 */
const UNUSED_AT_RUNTIME = [/^assets\/manifest\.json$/, /^assets\/characters\/[^/]+\.json$/, /-portrait\.webp$/, /^assets\/ui\/cream-pill\.webp$/];

/**
 * Content-Security-Policy for the production build (GitHub Pages cannot send
 * headers, so it ships as a meta tag). Scripts only from this site, no eval;
 * images may be data:/blob: (Phaser's loader and default textures); inline
 * style attributes stay allowed because Phaser measures the iOS viewport with
 * one. The dev server is untouched (Vite injects its own scripts there).
 */
const CSP = [
  "default-src 'self'",
  "script-src 'self'",
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob:",
  "font-src 'self'",
  "connect-src 'self'",
  "media-src 'self' data: blob:",
  "worker-src 'self'",
  "manifest-src 'self'",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'none'",
].join('; ');

function contentSecurityPolicy(): Plugin {
  return {
    name: 'dino-csp',
    apply: 'build',
    transformIndexHtml(html) {
      return html.replace('<meta charset="UTF-8" />', `<meta charset="UTF-8" />\n    <meta http-equiv="Content-Security-Policy" content="${CSP}" />`);
    },
  };
}

/**
 * Emits dist/sw.js with a precache list of every built file plus public assets
 * and a content-derived version, so caches are versioned per build.
 */
function serviceWorker(): Plugin {
  return {
    name: 'dino-service-worker',
    apply: 'build',
    generateBundle(_options, bundle) {
      const publicDir = join(process.cwd(), 'public');
      const publicFiles = listFiles(publicDir).filter((f) => !f.endsWith('.DS_Store') && !UNUSED_AT_RUNTIME.some((re) => re.test(f)));
      // Every target browser uses woff2; legacy .woff fallbacks stay network-only.
      const built = Object.keys(bundle).filter((f) => !f.endsWith('.map') && !f.endsWith('.woff'));
      const hash = createHash('sha256');
      for (const f of built.sort()) {
        const item = bundle[f];
        hash.update(f);
        if (item && item.type === 'asset') hash.update(typeof item.source === 'string' ? item.source : Buffer.from(item.source));
        if (item && item.type === 'chunk') hash.update(item.code);
      }
      for (const f of publicFiles.sort()) hash.update(f).update(readFileSync(join(publicDir, f)));
      const version = hash.digest('hex').slice(0, 12);
      const precache = ['./', ...new Set([...built, ...publicFiles])].map((f) => (f === './' ? f : `./${f}`));
      const template = readFileSync(join(process.cwd(), 'tools/build/sw-template.js'), 'utf8');
      const source = template.replace('__VERSION__', version).replace('__PRECACHE__', JSON.stringify(precache, null, 1));
      this.emitFile({ type: 'asset', fileName: 'sw.js', source });
    },
  };
}

// Base path is relative so the build works from any static-host sub-path.
export default defineConfig({
  base: './',
  plugins: [contentSecurityPolicy(), serviceWorker()],
  build: {
    target: 'es2022',
    assetsInlineLimit: 0,
    chunkSizeWarningLimit: 1600,
    rollupOptions: {
      output: {
        manualChunks(id: string) {
          if (id.includes('node_modules/phaser')) return 'phaser';
          return undefined;
        },
      },
    },
  },
  server: { host: true, port: 5173 },
  preview: { host: true, port: 4173 },
  test: {
    include: ['tests/domain/**/*.test.ts'],
    environment: 'node',
  },
});
